        SourceCatalog.put("ui.guideIntro", "\u042d\u0442\u043e\u0442\u0020\u0431\u043b\u043e\u043a\u0020\u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u044f\u0020\u043f\u043e\u043c\u043e\u0433\u0430\u0435\u0442\u0020\u0432\u0435\u0441\u0442\u0438\u0020\u0441\u043f\u0438\u0441\u043e\u043a\u0020\u043e\u0431\u0438\u0434\u0020\u2014\u0020\u043e\u0434\u043d\u0443\u0020\u0438\u0437\u0020\u0447\u0430\u0441\u0442\u0435\u0439\u0020\u0034\u0020\u0448\u0430\u0433\u0430\u002e\u0020\u0420\u0430\u0431\u043e\u0442\u0430\u0439\u0442\u0435\u0020\u0432\u043c\u0435\u0441\u0442\u0435\u0020\u0441\u043e\u0020\u0441\u043f\u043e\u043d\u0441\u043e\u0440\u043e\u043c\u0020\u0438\u0020\u043b\u0438\u0442\u0435\u0440\u0430\u0442\u0443\u0440\u043e\u0439\u0020\u0410\u041d\u002e\u0020\u041f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435\u0020\u043d\u0435\u0020\u0437\u0430\u043c\u0435\u043d\u044f\u0435\u0442\u0020\u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u0443\u002c\u0020\u0433\u0440\u0443\u043f\u043f\u0443\u0020\u0438\u0020\u0441\u043f\u043e\u043d\u0441\u043e\u0440\u0430\u002e")
